using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.JNT.JuntaDetalle;namespace GraphApi.Services.JNT.JuntaDetalle{    public class JuntaDetalleService : IJuntaDetalleService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public JuntaDetalleService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadJuntaDetalle>> GetJuntaDetalles(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM jnt.JuntaDetalle (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadJuntaDetalle>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetJuntaDetallesDynamic(            int? juntaDetalleID,            int? juntaID,            string? contenido,            DateTime? fechaRegistro,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "JuntaDetalleID, JuntaID, Contenido, FechaRegistro, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM jnt.JuntaDetalle (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (juntaDetalleID.HasValue)            {                vSql.Append(" AND JuntaDetalleID = @JuntaDetalleID");                vParameters.Add("JuntaDetalleID",juntaDetalleID);            }            if (!string.IsNullOrWhiteSpace(contenido))            {                vSql.Append(" AND Contenido LIKE @Contenido");                vParameters.Add("Contenido",$"%{contenido}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadJuntaDetalle> CreateJuntaDetalle(clCreateJuntaDetalle objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO jnt.JuntaDetalle                (JuntaID, Contenido, FechaRegistro, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@JuntaID, @Contenido, @FechaRegistro, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.JuntaID,                objInput.Contenido,                objInput.FechaRegistro,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT JuntaDetalleID, JuntaID, Contenido, FechaRegistro, bEliminado                FROM jnt.JuntaDetalle (NOLOCK)                WHERE JuntaDetalleID = @JuntaDetalleID;";            var vReadParams = new { JuntaDetalleID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadJuntaDetalle>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el JuntaDetalle con ID {vNewId}.");            return vCreated;        }        public async Task<clReadJuntaDetalle?> UpdateJuntaDetalle(clUpdateJuntaDetalle objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("JuntaDetalleID", objInput.JuntaDetalleID);            if (objInput.JuntaID != null)            {                vSets.Add("JuntaID = @JuntaID");                vParameters.Add("JuntaID", objInput.JuntaID);            }            if (objInput.Contenido is not null)            {                vSets.Add("Contenido = @Contenido");                vParameters.Add("Contenido", objInput.Contenido);            }            if (objInput.FechaRegistro != null)            {                vSets.Add("FechaRegistro = @FechaRegistro");                vParameters.Add("FechaRegistro", objInput.FechaRegistro);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE jnt.JuntaDetalle                SET {vSetClause}                WHERE JuntaDetalleID = @JuntaDetalleID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT JuntaDetalleID, JuntaID, Contenido, FechaRegistro, bEliminado                FROM jnt.JuntaDetalle (NOLOCK)                WHERE JuntaDetalleID = @JuntaDetalleID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadJuntaDetalle>(sSelect, new {  objInput.JuntaDetalleID });        }        public async Task<bool> DeleteJuntaDetalle(int nJuntaDetalleID)        {            const string sSql = @"                DELETE FROM jnt.JuntaDetalle                WHERE JuntaDetalleID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nJuntaDetalleID });            return vAffected > 0;        }    }}